/**
 * Storybook prepends a "debug banner" to failing test error messages so users can jump straight to
 * the failing story (see `modifyErrorMessage` in the Vitest addon setup file). The banner is a
 * single, ANSI-colored line of the form:
 *
 * `\n\x1B[34mClick to debug the error directly in Storybook: <url>\x1B[39m\n\n<actual message>`
 *
 * These helpers strip both the ANSI escape sequences and the banner line so the real error message
 * surfaces cleanly.
 */
// eslint-disable-next-line no-control-regex
const ANSI_ESCAPE_PATTERN = /\x1B\[[0-9;]*m/g;
const DEBUG_BANNER_PATTERN = /Click to debug the error directly in Storybook:.*/g;

/** Remove Storybook debug banners and ANSI color codes from a piece of text. */
function stripDebugBanner(input: string): string {
  return input.replace(ANSI_ESCAPE_PATTERN, '').replace(DEBUG_BANNER_PATTERN, '');
}

/** Return the first line of `input` that has non-whitespace content, trimmed. */
function firstNonEmptyLine(input: string): string {
  for (const line of input.split('\n')) {
    const trimmed = line.trim();
    if (trimmed) {
      return trimmed;
    }
  }
  return '';
}

/**
 * Derive a concise, human-readable error message from an error's message and/or stack.
 *
 * - Storybook debug banners are stripped from the message.
 * - Returns the first non-empty line of the cleaned message.
 * - Falls back to the first non-empty line of the stack trace when the message is empty.
 * - Returns `'unknown error'` when both message and stack are empty or undefined.
 */
export function extractErrorMessage(
  message: string | undefined,
  stack: string | undefined
): string {
  const messageLine = firstNonEmptyLine(stripDebugBanner(message ?? ''));
  if (messageLine) {
    return messageLine;
  }

  const stackLine = firstNonEmptyLine(stripDebugBanner(stack ?? ''));
  if (stackLine) {
    return stackLine;
  }

  return 'unknown error';
}

/**
 * Detect whether any of the given reports indicates an empty render.
 *
 * Returns `true` when a report of type `'render-analysis'` has a truthy `result.emptyRender` flag.
 */
export function detectEmptyRender(
  reports: readonly { type: string; result?: unknown }[] | undefined
): boolean {
  return (
    reports?.some(
      (report) =>
        report.type === 'render-analysis' &&
        (report.result as { emptyRender?: boolean } | undefined)?.emptyRender === true
    ) ?? false
  );
}

/** Normalize a raw status string into one of the canonical `StoryTestResult` statuses. */
function normalizeStatus(statusRaw: string | undefined): StoryTestResult['status'] {
  const normalized = statusRaw?.toLowerCase();
  if (normalized === 'pass' || normalized === 'passed') {
    return 'PASS';
  }
  if (normalized === 'fail' || normalized === 'failed') {
    return 'FAIL';
  }
  return 'PENDING';
}

/**
 * Normalize a raw test result (as produced by a test runner) into a shared {@link StoryTestResult}.
 *
 * Returns `null` when there is no `storyId`, as the result cannot be attributed to a story.
 */
export function toStoryTestResult(input: {
  storyId: string | undefined;
  statusRaw: string | undefined;
  errors?: readonly { message?: string; stack?: string }[];
  reports?: readonly { type: string; result?: unknown }[];
}): StoryTestResult | null {
  const { storyId, statusRaw, errors, reports } = input;

  if (storyId === undefined) {
    return null;
  }

  const status = normalizeStatus(statusRaw);

  const firstError = errors?.[0];
  const error = firstError ? extractErrorMessage(firstError.message, firstError.stack) : undefined;
  const stack = firstError?.stack;

  // Only PASS results can be considered empty renders. A failing story that renders nothing is
  // simply a failure.
  const emptyRender = status === 'PASS' && detectEmptyRender(reports);

  return {
    storyId,
    status,
    error,
    stack,
    emptyRender,
  };
}
